            readonly tipo_atividade: components["schemas"]["TipoAtividadeEnum"];
            readonly tipo_atividade_display: string;
            readonly status: components["schemas"]["StatusAtividadeEnum"];
            readonly status_display: string;
            /** Status de Sync Google Calendar */
            readonly google_calendar_sync_status: components["schemas"]["GoogleCalendarSyncStatusEnum"];
            readonly atrasada: boolean;
            readonly cor: string;
            /**
             * Data de Início
             * Format: date-time
             */
            readonly data_inicio: string;
            /**
             * Data de Fim
             * Format: date-time
             */
            readonly data_fim: string;
            readonly tecnico_responsavel: components["schemas"]["UsuarioRef"];
            readonly municipio: components["schemas"]["MunicipioNested"];
